{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.warehouse_mp_performance AS WITH uc AS ( SELECT * FROM snitch_db.maplemonk.unicommerce_fact_items_intermediate_2024 WHERE marketplace_mapped NOT IN ( \'STORE\',\'MYNTRA\',\'AJIO\',\'FLIPKART\',\'SHOPIFY\',\'AMAZON\',\'NYKAA.COM\',\'NYKAA_FASHION\',\'NOON\',\'TEST VR MALL\',\'CUSTOM\',\'B2B CORPORATE CHANNEL\',\'SNITCH HQ\',\'CRED\',\'POPCLUB\',\'SAPL_WH_TRANSFERS\',\'SNAPMINT\',\'COCOBLU_NORTH\',\'COCOBLU_WH2\',\'COCOBLU_WH1\',\'COCOBLU\') AND order_date >= current_date-180 ), mp AS ( SELECT UPPER(TRIM(SO_NUMBER)) AS mp_so_key, SO_NUMBER AS mp_so_number, PO_NUMBER AS mp_po_number, DC_NUMBER AS mp_dc_number, LR_NO AS mp_lr_no, INVOICE_NUMBER AS mp_invoice_number, CHANNEL AS mp_channel, MARKETPLACE_NAME AS mp_marketplace_name, FACILITY AS mp_facility, CITY AS mp_city, \"Address \" AS mp_address, STATUS AS mp_status, DELIVERY_STATUS AS mp_delivery_status, CURRENT_REMARKS AS mp_current_remarks, REMARKS AS mp_remarks, LOGISTICS_PARTNER AS mp_logistics_partner, NEW_SLOT AS mp_new_slot, PROCESSING_TAT AS mp_processing_tat, TRY_TO_NUMBER(BOX_COUNT) AS mp_box_count_raw, TRY_TO_NUMBER(ACTUALWEIGHT) AS mp_actual_weight_raw, CASE WHEN TRY_TO_DATE(DATE, \'DD/MM/YYYY\') >= \'2024-01-01\' THEN TRY_TO_DATE(DATE, \'DD/MM/YYYY\') END AS mp_date, CASE WHEN TRY_TO_DATE(RTS_DATE, \'YYYY-MM-DD\') >= \'2024-01-01\' THEN TRY_TO_DATE(RTS_DATE, \'YYYY-MM-DD\') END AS mp_rts_date, CASE WHEN TRY_TO_DATE(SLOT_DATE, \'YYYY-MM-DD\') >= \'2024-01-01\' THEN TRY_TO_DATE(SLOT_DATE, \'YYYY-MM-DD\') END AS mp_slot_date, CASE WHEN TRY_TO_DATE(PICKUP_DATE, \'YYYY-MM-DD\') >= \'2024-01-01\' THEN TRY_TO_DATE(PICKUP_DATE, \'YYYY-MM-DD\') END AS mp_pickup_date, CASE WHEN TRY_TO_DATE(DISPATCH_DATE, \'YYYY-MM-DD\') >= \'2024-01-01\' THEN TRY_TO_DATE(DISPATCH_DATE, \'YYYY-MM-DD\') END AS mp_dispatch_date, CASE WHEN TRY_TO_DATE(DELIVERED_DATE, \'YYYY-MM-DD\') >= \'2024-01-01\' THEN TRY_TO_DATE(DELIVERED_DATE, \'YYYY-MM-DD\') END AS mp_delivered_date FROM snitch_db.maplemonk.gs_marketplace_wh_tracker WHERE SO_NUMBER IS NOT NULL AND TRIM(SO_NUMBER) <> \'\' AND UPPER(TRIM(SO_NUMBER)) <> \'SO_NUMBER\' QUALIFY ROW_NUMBER() OVER ( PARTITION BY UPPER(TRIM(SO_NUMBER)) ORDER BY CASE WHEN TRY_TO_DATE(DISPATCH_DATE,\'YYYY-MM-DD\') >= \'2024-01-01\' THEN TRY_TO_DATE(DISPATCH_DATE,\'YYYY-MM-DD\') END DESC NULLS LAST ) = 1 ), joined AS ( SELECT uc.*, mp.mp_so_number, mp.mp_po_number, mp.mp_dc_number, mp.mp_lr_no, mp.mp_invoice_number, mp.mp_channel, mp.mp_marketplace_name, mp.mp_facility, mp.mp_city, mp.mp_address, mp.mp_status, mp.mp_delivery_status, mp.mp_current_remarks, mp.mp_remarks, mp.mp_logistics_partner, mp.mp_new_slot, mp.mp_processing_tat, mp.mp_date, mp.mp_rts_date, mp.mp_slot_date, mp.mp_pickup_date, mp.mp_dispatch_date, mp.mp_delivered_date, mp.mp_box_count_raw, mp.mp_actual_weight_raw, CASE WHEN mp.mp_so_key IS NOT NULL THEN 1 ELSE NULL END AS mp_tracker_match_flag, COALESCE(dispatched_timestamp, packed_time, packed_timestamp) AS wh_dispatch_ts, ROW_NUMBER() OVER ( PARTITION BY UPPER(TRIM(uc.order_name)) ORDER BY uc.saleorderitemcode ) AS so_line_seq FROM uc LEFT JOIN mp ON UPPER(TRIM(uc.order_name)) = mp.mp_so_key ) SELECT joined.* EXCLUDE (mp_box_count_raw, mp_actual_weight_raw), suborder_quantity AS item_qty, CASE WHEN sale_order_item_status NOT IN (\'CANCELLED\',\'UNFULFILLABLE\') AND wh_dispatch_ts IS NOT NULL THEN suborder_quantity ELSE 0 END AS item_qty_dispatched, CASE WHEN sale_order_item_status = \'UNFULFILLABLE\' THEN suborder_quantity ELSE 0 END AS item_qty_unfulfillable, CASE WHEN sale_order_item_status = \'CANCELLED\' THEN suborder_quantity ELSE 0 END AS item_qty_cancelled, CASE WHEN sale_order_item_status NOT IN (\'CANCELLED\',\'UNFULFILLABLE\') AND wh_dispatch_ts IS NULL THEN suborder_quantity ELSE 0 END AS item_qty_open, CASE WHEN so_line_seq = 1 THEN mp_box_count_raw END AS mp_box_count_so, CASE WHEN so_line_seq = 1 THEN mp_actual_weight_raw END AS mp_actual_weight_so, CASE WHEN so_line_seq = 1 THEN 1 ELSE 0 END AS is_so_header, CASE WHEN mp_tracker_match_flag IS NULL THEN 0 WHEN sale_order_item_status IN (\'CANCELLED\',\'UNFULFILLABLE\') THEN 0 ELSE 1 END AS sla_eligible, CASE WHEN mp_tracker_match_flag IS NULL THEN \'NO TRACKER MATCH\' WHEN sale_order_item_status = \'CANCELLED\' THEN \'CANCELLED\' WHEN sale_order_item_status = \'UNFULFILLABLE\' THEN \'UNFULFILLABLE\' WHEN mp_dispatch_date IS NULL THEN \'PENDING - NO TRACKER DISPATCH DATE\' WHEN wh_dispatch_ts IS NULL AND mp_dispatch_date >= CURRENT_DATE THEN \'FUTURE SLA\' WHEN wh_dispatch_ts IS NULL THEN \'BREACHED - PENDING FOR PROCESS\' WHEN wh_dispatch_ts::DATE <= mp_dispatch_date THEN \'WITHIN SLA\' ELSE \'BREACHED\' END AS processing_sla, CASE WHEN mp_tracker_match_flag IS NULL THEN \'NO TRACKER MATCH\' WHEN sale_order_item_status IN (\'CANCELLED\',\'UNFULFILLABLE\') THEN \'CANCELLED\' WHEN mp_dispatch_date IS NULL THEN \'PENDING - NO TRACKER DISPATCH DATE\' WHEN mp_pickup_date IS NULL AND mp_dispatch_date >= CURRENT_DATE THEN \'FUTURE SLA\' WHEN mp_pickup_date IS NULL THEN \'BREACHED - PENDING FOR PICKUP\' WHEN mp_pickup_date <= mp_dispatch_date THEN \'WITHIN SLA\' ELSE \'BREACHED\' END AS pickup_sla, CASE WHEN mp_tracker_match_flag IS NULL THEN \'NO TRACKER MATCH\' WHEN sale_order_item_status IN (\'CANCELLED\',\'UNFULFILLABLE\') THEN \'CANCELLED\' WHEN mp_slot_date IS NULL THEN \'PENDING - NO SLOT DATE\' WHEN mp_delivered_date IS NULL AND mp_slot_date >= CURRENT_DATE THEN \'FUTURE SLA\' WHEN mp_delivered_date IS NULL THEN \'BREACHED - PENDING FOR DELIVERY\' WHEN mp_delivered_date <= mp_slot_date THEN \'WITHIN SLA\' ELSE \'BREACHED\' END AS logistics_sla, CASE WHEN mp_delivery_status ILIKE \'%reject%\' THEN \'REJECTED\' WHEN mp_delivery_status ILIKE \'%partial%\' THEN \'PARTIAL\' WHEN mp_delivery_status ILIKE \'%return%\' OR mp_delivery_status ILIKE \'%rto%\' THEN \'RETURNED\' WHEN mp_delivered_date IS NOT NULL THEN \'ACCEPTED\' ELSE NULL END AS mp_receipt_outcome, DATEDIFF(\'day\', uc_created::DATE, wh_dispatch_ts::DATE) AS processing_days, DATEDIFF(\'day\', mp_dispatch_date, wh_dispatch_ts::DATE) AS processing_sla_lag_days, DATEDIFF(\'day\', mp_dispatch_date, mp_pickup_date) AS pickup_sla_lag_days, DATEDIFF(\'day\', mp_slot_date, mp_delivered_date) AS logistics_sla_lag_days, DATEDIFF(\'day\', mp_pickup_date, mp_delivered_date) AS transit_days, CASE WHEN mp_delivered_date IS NULL THEN DATEDIFF(\'day\', uc_created::DATE, CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP())::DATE) END AS open_order_ageing_days FROM joined ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            